protected void init()
{
    api = XAPI_APIS::GetProductAndPrices;
    super();
}

protected void postRun()
{
    EGS_API_DataContract_Response res;

    if (!responseText)
    {
        return;
    }

    res = FormJsonSerializer::deserializeObject(classNum(EGS_API_DataContract_Response), responseText);

    if (status == XAPI_APIStatus::Error)
    {
        return;
    }

    if (res.parmStatus() && strLwr(res.parmStatus()) != 'ok')
    {
        status       = XAPI_APIStatus::Error;
        errorMessage = res.parmMessage();
        return;
    }

    logKey   = "ProductAndPrices";
    logValue = res.parmMessage();
}

protected str body()
{
    Map configMap;

    configMap = new Map(Types::String, Types::String);
    configMap.insert('<InstallationNum>', XAPI_APILogTable::getValueByKey(XAPI_APIS::CreateInstallation, 'InstNum'));
    configMap.insert('<ContractNum>',     XAPI_APILogTable::getValueByKey(XAPI_APIS::CreateContract,     'ContractNum'));

    return this.prepareBody(configMap);
}
